ddl:
CREATE TABLE User_Table (
    Nickname VARCHAR(255),
    Password VARCHAR(255),
    Profile_Picture BLOB,
    Username VARCHAR(255) PRIMARY KEY
);

CREATE TABLE Guide_Table (
    Category VARCHAR(255),
    Content VARCHAR(255),
    Guide_Title VARCHAR(255) PRIMARY KEY,
    Tags VARCHAR(255)
);

CREATE TABLE Restaurant_Table (
    Image BLOB,
    Introduction VARCHAR(255),
    Location VARCHAR(255),
    Restaurant_Name VARCHAR(255) PRIMARY KEY
);

CREATE TABLE Hotel_Table (
    Hotel_Name VARCHAR(255) PRIMARY KEY,
    Image BLOB,
    Introduction VARCHAR(255),
    Location VARCHAR(255)
);

CREATE TABLE Scenic_Spot_Table (
    Address VARCHAR(255),
    Days INTEGER,
    Image BLOB,
    Introduction VARCHAR(255),
    Opening_Hours VARCHAR(255),
    Scenic_Spot_Name VARCHAR(255) PRIMARY KEY,
    Tips VARCHAR(255)
);

CREATE TABLE Route (
    Content VARCHAR(255),
    Introduction VARCHAR(255),
    Route_Name VARCHAR(255) PRIMARY KEY,
    Tags VARCHAR(255)
);

CREATE TABLE Write_Guide_Table (
    Guide_Title VARCHAR(255) NOT NULL,
    Username VARCHAR(255) NOT NULL,
    PRIMARY KEY (Username, Guide_Title),
    FOREIGN KEY (Guide_Title) REFERENCES Guide_Table(Guide_Title),
    FOREIGN KEY (Username) REFERENCES User_Table(Username)
);
